SELECT CASE WHEN (pp.take_profit - pp.entry_price) / NULLIF(pp.entry_price - pp.stop_loss, 0) < 0.5 THEN 'a_lt0.5' WHEN (pp.take_profit - pp.entry_price) / NULLIF(pp.entry_price - pp.stop_loss, 0) < 1 THEN 'b_0.5-1' WHEN (pp.take_profit - pp.entry_price) / NULLIF(pp.entry_price - pp.stop_loss, 0) < 1.5 THEN 'c_1-1.5' ELSE 'd_ge1.5' END AS rr_band, CASE WHEN wmp.entry_quality_score IS NULL THEN 'unknown' WHEN wmp.entry_quality_score >= 70 THEN 'ge70' WHEN wmp.entry_quality_score >= 55 THEN '55-69' WHEN wmp.entry_quality_score >= 51 THEN '51-54' WHEN wmp.entry_quality_score = 50 THEN 'eq50' ELSE 'lt50' END AS eq_band, COUNT(*) AS n, SUM(pp.realized_pnl > 0) AS wins, SUM(pp.realized_pnl < 0) AS losses, ROUND(SUM(pp.realized_pnl), 6) AS sum_pnl, ROUND(AVG(pp.realized_pnl), 6) AS avg_pnl FROM crypto_ai.paper_position pp LEFT JOIN crypto_ai.wallet_managed_position wmp ON wmp.entry_signal_id = pp.signal_id WHERE pp.opened_at >= '2026-10-11 00:00:00' AND pp.status IN ('CLOSED', 'STOPPED') GROUP BY rr_band, eq_band ORDER BY rr_band, eq_band;